import { DatabaseSync } from "node:sqlite"
import { parseArgs } from "node:util"
import { Effect } from "effect"

const main = Effect.try({
  try: () => {
    const { values } = parseArgs({
      options: {
        database: { type: "string", default: ".cache/builds.sqlite" },
        sql: { type: "string" }
      }
    })
    if (!values.sql) {
      throw new Error("Usage: inspect-artifacts [--database PATH] --sql QUERY")
    }
    const database = new DatabaseSync(values.database, { readOnly: true })
    try {
      const rows = database.prepare(values.sql).all()
      process.stdout.write(`${JSON.stringify(rows)}\n`)
    } finally {
      database.close()
    }
  },
  catch: (cause) => new Error("Artifact inspection failed", { cause })
})

Effect.runPromise(main).catch((error) => {
  process.stderr.write(`${error.message}\n`)
  process.exitCode = 1
})
